import sys

def main():
    data = sys.stdin.read().splitlines()
    n = int(data[0].strip())
    words = data[1].split() if len(data) > 1 else []
    groups = {}
    for w in words:
        l = len(w)
        groups.setdefault(l, []).append(w)
    for length in sorted(groups):
        print(f"{length}: [{', '.join(groups[length])}]")

if __name__ == "__main__":
    main()
